"""
icons.py - Iconos pre-renderizados en Base64 para AuditFlow
"""

import base64
from io import BytesIO
from PIL import Image, ImageOps
import customtkinter as ctk

_ICONS_B64 = {}

_ICONS_B64["trash-2"] = ""

_ICONS_B64["camera"] = ""

_ICONS_B64["paperclip"] = ""

_ICONS_B64["download"] = ""

_ICONS_B64["eye"] = ""

_ICONS_B64["file-text"] = ""

_ICONS_B64["save"] = ""

_ICONS_B64["image"] = ""

_ICONS_B64["video"] = ""

_ICONS_B64["check"] = ""

_ICONS_B64["wifi-off"] = ""

_ICONS_B64["plus"] = ""

_ICONS_B64["x"] = ""

_ICONS_B64["cloud"] = ""

_ICONS_B64["layout-dashboard"] = ""


_IMAGE_CACHE = {}

def get_icon(name: str, size: tuple = (20, 20), color: str = None) -> ctk.CTkImage:
    """Devuelve un CTkImage coloreado dinámicamente si se especifica color."""
    cache_key = f"{name}_{size[0]}x{size[1]}_{color}"
    if cache_key in _IMAGE_CACHE:
        return _IMAGE_CACHE[cache_key]

    if name not in _ICONS_B64:
        return None

    img_data = base64.b64decode(_ICONS_B64[name])
    img = Image.open(BytesIO(img_data)).convert("RGBA")

    if color:
        # Colorear el PNG negro con Pillow (reemplazar pixeles negros)
        r, g, b = ImageColor.getrgb(color)
        data = img.getdata()
        new_data = []
        for px in data:
            if px[3] > 0: # Si no es transparente
                new_data.append((r, g, b, px[3]))
            else:
                new_data.append(px)
        img.putdata(new_data)

    ctk_img = ctk.CTkImage(light_image=img, dark_image=img, size=size)
    _IMAGE_CACHE[cache_key] = ctk_img
    return ctk_img

from PIL import ImageColor